def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    k = len(alphabet)
    char_id = {ch: i for i, ch in enumerate(alphabet)}

    nxt = [[-1] * k]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_id[ch]
            if nxt[node][c] == -1:
                nxt[node][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            node = nxt[node][c]
        bad[node] = True

    fail = [0] * len(nxt)
    q = deque()

    for c in range(k):
        child = nxt[0][c]
        if child == -1:
            nxt[0][c] = 0
        else:
            q.append(child)

    while q:
        v = q.popleft()
        bad[v] = bad[v] or bad[fail[v]]

        for c in range(k):
            child = nxt[v][c]
            if child == -1:
                nxt[v][c] = nxt[fail[v]][c]
            else:
                fail[child] = nxt[fail[v]][c]
                q.append(child)

    safe_states = [i for i in range(len(nxt)) if not bad[i]]
    index = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        i = index[state]
        for c in range(k):
            target = nxt[state][c]
            if not bad[target]:
                matrix[i][index[target]] += 1

    def multiply(a, b):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            for t in range(size):
                if a[i][t]:
                    x = a[i][t]
                    for j in range(size):
                        result[i][j] = (result[i][j] + x * b[t][j]) % MOD
        return result

    def vector_multiply(vec, mat):
        result = [0] * size
        for i in range(size):
            if vec[i]:
                x = vec[i]
                for j in range(size):
                    result[j] = (result[j] + x * mat[i][j]) % MOD
        return result

    vector = [0] * size
    vector[index[0]] = 1

    while n:
        if n & 1:
            vector = vector_multiply(vector, matrix)
        matrix = multiply(matrix, matrix)
        n >>= 1

    return sum(vector) % MOD
